/* Palette: #1a1a2e (bg), #16213e (card), #e94560 (accent), #f0f0f0 (text), #0f3460 (button) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #f0f0f0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: #16213e;
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 24px;
  color: #e94560;
  letter-spacing: 0.5px;
}

.meter-display {
  background: #0f3460;
  border-radius: 12px;
  padding: 24px 16px;
  margin-bottom: 24px;
  border: 2px solid #e94560;
}

.time-display {
  font-size: 3rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 2px;
  color: #f0f0f0;
  line-height: 1.2;
}

.price-display {
  font-size: 1.5rem;
  color: #e94560;
  margin-top: 8px;
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-bottom: 20px;
}

button {
  font-family: inherit;
  font-size: 1.125rem;
  font-weight: 600;
  padding: 14px 24px;
  border: 2px solid #e94560;
  border-radius: 10px;
  background: #0f3460;
  color: #f0f0f0;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  min-width: 100px;
}

button:hover {
  background: #e94560;
  color: #1a1a2e;
}

button:focus-visible {
  outline: 3px solid #f0f0f0;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
  background: #e94560;
  color: #1a1a2e;
}

button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
}

button:disabled:hover {
  background: #0f3460;
  color: #f0f0f0;
}

.clear-btn {
  border-color: #f0f0f0;
}

.clear-btn:hover {
  background: #f0f0f0;
  color: #1a1a2e;
}

.hint {
  font-size: 0.875rem;
  color: #a0a0b0;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .time-display {
    font-size: 2.25rem;
  }
  button {
    padding: 12px 16px;
    min-width: 80px;
    font-size: 1rem;
  }
}

(function () {
  'use strict';

  var MAX_MINUTES = 180;
  var RATE_PER_HOUR = 2.00;

  var minutes = 0;

  var timeDisplay = document.getElementById('time-display');
  var priceDisplay = document.getElementById('price-display');
  var add15 = document.getElementById('add-15');
  var add60 = document.getElementById('add-60');
  var clearBtn = document.getElementById('clear');

  function formatTime(totalMinutes) {
    var h = Math.floor(totalMinutes / 60);
    var m = totalMinutes % 60;
    return h + ':' + (m < 10 ? '0' : '') + m;
  }

  function formatPrice(totalMinutes) {
    var price = (totalMinutes / 60) * RATE_PER_HOUR;
    return '$' + price.toFixed(2);
  }

  function render() {
    timeDisplay.textContent = formatTime(minutes);
    priceDisplay.textContent = formatPrice(minutes);
    var atMax = minutes >= MAX_MINUTES;
    add15.disabled = atMax;
    add60.disabled = atMax;
  }

  function addMinutes(amount) {
    minutes = Math.min(minutes + amount, MAX_MINUTES);
    render();
  }

  add15.addEventListener('click', function () {
    addMinutes(15);
  });

  add60.addEventListener('click', function () {
    addMinutes(60);
  });

  clearBtn.addEventListener('click', function () {
    minutes = 0;
    render();
  });

  render();
})();
